// Kalender (ALLY 29, BA5, Stefan 20.10.2026; Migration 205, interner Kalender, Stefan 04.11.2026): Die Seite gehört zum Basispaket und zeigt alles, was zum
// internen Kalender gehört: eigene Termine (kalender_termine), die Einträge der Pakete über ihre Kalenderquelle (Social-Media Management: Aufgaben, Termine,
// Deadlines, Veröffentlichungen, Zeitraum der Kampagnen) und zusätzlich den Google Kalender, wenn eine Kalender-ID hinterlegt ist (ALLY 13 wie bisher).
// Filter ab/Zeitraum/Suche, Tabelle sortierbar; Seitenfenster je Eintrag: interner Termin ändern oder in den Papierkorb (alle, die ihn sehen, Stefan 09:05),
// Eintrag eines Pakets: Datum ändern, soweit das Paket es erlaubt, und „Öffnen“; Google-Termin wie bisher (termin_aendern, termin_loeschen).
// „Neuer Termin“: Feld „Kalender“ Intern (vorbelegt) oder Google, ohne Kalender-ID nur intern (Stefan 09:05). Papierkorb (papierkorb=1) nach Regel E13.
// Daten: "Daten laden" (k = kalender_web_seite, w = arbeit_web_seite 'kalender' für den Google Kalender), Google-Termine aus "Arbeitsdaten laden (ALLY 13)".
// Karten Offen/Meldungen: Nebentext in den Text (schmale Karten neben dem Seitenfenster, sonst bricht der Text zeichenweise um)
const knapp = u => { if (u && Array.isArray(u.karten)) for (const k of u.karten) for (const e of k.eintraege || []) if (e.neben) { e.text = String(e.text || '') + ' · ' + String(e.neben); delete e.neben; } return u; };
const E = $('Start').first().json;
const D = $('Daten laden').first().json || {};
const X = $('Arbeitsdaten laden (ALLY 13)').isExecuted ? ($('Arbeitsdaten laden (ALLY 13)').first().json || {}) : {};
const F = E.funktion || {};
const P = E.parameter || {};
const s = v => String(v ?? '');
const L = v => Array.isArray(v) ? v : [];
const titel = s(F.name || 'Kalender');
const pk = s(P.papierkorb) === '1';
const kopf = { schluessel: 'kalender', art: 'funktion', titel, beschreibung: s(F.beschreibung), krumen: [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel }] };
const einst = { seite: 'einstellungen', parameter: { bereich: /^[a-z0-9-]{1,40}$/.test(s(F.einstellungen_ziel)) ? s(F.einstellungen_ziel) : 'kalender' } };
kopf.zahnrad = { ziel: einst };
const K = D.k || {};
const W = D.w || {};
if (D.ok !== true || K.ok !== true) return [{ json: { inhalt: { seite: kopf, bloecke: [{ typ: 'hinweis', ton: 'warn',
  text: K.erlaubt === false ? 'Den Kalender darfst du nicht nutzen.' : 'Der Kalender konnte nicht geladen werden. Bitte neu laden.' }] } } }];
const googleDa = !!W.kalender_id;
const G = googleDa ? (X.kalender || null) : null;
const tagText = t => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s(t)); if (!m) return s(t);
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])); return ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'][d.getUTCDay()] + ', ' + m[3] + '.' + m[2] + '.' + m[1]; };
const tage = e => tagText(e.tag) + (e.bis_tag && e.bis_tag !== e.tag ? ' – ' + tagText(e.bis_tag) : '');
const zeitText = e => e.ganztags ? 'ganztägig' : (s(e.von) + (e.bis ? '–' + s(e.bis) : ''));
const heute = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin' }).format(new Date());
const jetzt = new Intl.DateTimeFormat('de-DE', { timeZone: 'Europe/Berlin', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());
const filterWerte = Object.assign({}, P.von ? { von: P.von } : {}, P.tage ? { tage: P.tage } : {}, P.q ? { q: P.q } : {});
const hier = (extra, anker) => ({ seite: 'kalender', parameter: Object.assign({}, filterWerte, pk ? { papierkorb: '1' } : {}, extra || {}), anker });
const ZR = { '1': '1 Tag', '7': '1 Woche', '14': '2 Wochen', '31': '1 Monat', '62': '2 Monate' };
const personen = L(K.personen).map(p => ({ wert: s(p.wert), text: s(p.text) }));
const ich = s(K.ich);

// Google-Termine in die gemeinsame Form (ALLY 13: id, titel, tag, von, bis, ganz, start, ende, ende_tag, ort, notiz/beschreibung, notiz_fest)
const google = G && G.ok === true ? L(G.termine).map(t => ({ quelle: 'google', id: 'g-' + s(t.id), gid: s(t.id), art_text: 'Google Kalender', titel: s(t.titel), tag: s(t.tag),
  bis_tag: t.ganz ? s(t.ende_tag || t.tag) : (/^\d{4}-\d{2}-\d{2}/.test(s(t.ende)) ? s(t.ende).slice(0, 10) : s(t.tag)), von: s(t.von), bis: s(t.bis), ganztags: !!t.ganz,
  ort: s(t.ort), notiz: s(t.notiz), g: t })) : [];
const eintraege = L(K.eintraege).filter(e => e && e.id).concat(google);
const vergleich = (a, b) => s(a.tag).localeCompare(s(b.tag)) || (b.ganztags ? 1 : 0) - (a.ganztags ? 1 : 0) || s(a.von).localeCompare(s(b.von)) || s(a.titel).localeCompare(s(b.titel), 'de');
eintraege.sort(vergleich);

// Meldungen: Google antwortet nicht, eine Kalenderquelle eines Pakets scheitert
const meldungen = [];
if (googleDa && G === null) meldungen.push({ marke: { text: 'Fehler', ton: 'warn' }, text: 'Die Termine aus dem Google Kalender konnten nicht geladen werden.' });
else if (googleDa && G.ok !== true) meldungen.push({ marke: { text: 'Fehler', ton: 'warn' }, text: 'Der Google Kalender antwortet nicht: ' + s(G.fehler).slice(0, 200) });
for (const f of L(K.fehler)) meldungen.push({ marke: { text: 'Fehler', ton: 'warn' }, text: 'Die Einträge aus „' + s(f.name) + '“ konnten nicht geladen werden.' });

const gew = s(P.termin);
const sel = gew ? (eintraege.find(e => s(e.id) === gew) || (K.gewaehlt && s(K.gewaehlt.id) === gew ? K.gewaehlt : null)) : null;

// Felder eines Termins (intern und Google): Beginn und Ende immer (bei „ganztägig“ nimmt ALLY 20 die Tage), die Tage nur mit „ganztägig“
const zeitFelder = t => [
  { typ: 'text', name: 'titel', label: 'Titel', pflicht: true, wert: t ? s(t.titel) : '', breite: 'voll' },
  { typ: 'haken', name: 'ganztaegig', label: 'ganztägig', wert_an: '1', an: !!(t && t.ganztags), breite: 'voll' },
  { typ: 'datum_zeit', name: 'start', label: 'Beginn', wert: t && !t.ganztags ? s(t.start) : '' },
  { typ: 'datum_zeit', name: 'ende', label: 'Ende', wert: t && !t.ganztags ? s(t.ende) : '' },
  { typ: 'datum', name: 'start_tag', label: 'Erster Tag (ganztägig)', wert: t ? s(t.tag) : '', zeigen_wenn: { feld: 'ganztaegig', werte: ['1'] } },
  { typ: 'datum', name: 'ende_tag', label: 'Letzter Tag (ganztägig)', wert: t ? s(t.bis_tag || t.tag) : '', zeigen_wenn: { feld: 'ganztaegig', werte: ['1'] } },
  { typ: 'text', name: 'ort', label: 'Ort', wert: t ? s(t.ort) : '', breite: 'voll' }];
const personFelder = (t, nurIntern) => {
  const z = nurIntern ? { zeigen_wenn: { feld: 'kalender', werte: ['intern'] } } : {};
  const fu = t ? s(t.fuer) : ich;
  const opt = personen.some(p => p.wert === fu) ? personen : personen.concat(fu ? [{ wert: fu, text: s(t && t.fuer_name) || fu }] : []);
  const ein = t ? L(t.eingeladen).map(s) : [];
  const optE = personen.concat(ein.filter(x => !personen.some(p => p.wert === x)).map((x, i) => ({ wert: x, text: s(L(t && t.eingeladen_namen)[i]) || x })));
  return [
    Object.assign({ typ: 'auswahl', name: 'fuer', label: 'Für', wert: fu, optionen: opt, breite: 'voll' }, z),
    Object.assign({ typ: 'mehrfach', name: 'eingeladen', label: 'Eingeladen', wert: ein, optionen: optE, breite: 'voll',
      info: 'Den Termin sehen die Person, die ihn anlegt, die Person, für die er ist, und die Eingeladenen. Alle drei dürfen ihn ändern und in den Papierkorb legen.' }, z),
    { typ: 'versteckt', name: 'eingeladen_sichtbar', wert: '1' }];
};

const fenster = [];
let abschnitte, ueberblick;
if (pk) {
  // ---------- Papierkorb (Regel E13) ----------
  const PKL = L(K.papierkorb).filter(e => e && e.id);
  kopf.titel = 'Papierkorb';
  kopf.beschreibung = 'Termine im Papierkorb stehen nicht im Kalender und nicht im Kalender-Abo. Du kannst sie wiederherstellen oder endgültig löschen.';
  kopf.krumen = [{ text: 'Startseite', ziel: { seite: 'start' } }, { text: titel, ziel: { seite: 'kalender', parameter: filterWerte } }, { text: 'Papierkorb' }];
  if (PKL.length) kopf.aktionen = [{ text: 'Papierkorb leeren', aktion: 'kt_papierkorb_leeren', werte: { ids: PKL.map(e => s(e.id).slice(2)).join(',') },
    frage: 'Papierkorb endgültig leeren? ' + (PKL.length === 1 ? 'Der Termin im Papierkorb wird' : 'Alle ' + PKL.length + ' Termine im Papierkorb werden') + ' endgültig gelöscht. Das lässt sich nicht rückgängig machen.' }];
  abschnitte = [{ id: 'papierkorb', titel: 'Im Papierkorb', zahl: String(PKL.length), offen_standard: true, inhalt: [
    { typ: 'tabelle', id: 'papierkorb', titel: 'Im Papierkorb', spalten: [{ schluessel: 'titel', titel: 'Termin' }, { schluessel: 'tag', titel: 'Tag' }, { schluessel: 'geloescht', titel: 'Gelöscht' },
      { schluessel: 'aktion', titel: 'Aktion' }],
      zeilen: PKL.map(e => ({ aktiv: gew === s(e.id), zellen: { titel: { text: s(e.titel), ziel: hier({ termin: e.id }, 'a-papierkorb') }, tag: tage(e),
        geloescht: { text: s(e.geloescht_am), neben: e.geloescht_von_name ? 'von ' + s(e.geloescht_von_name) : '' },
        aktion: { aktionen: [
          { text: 'Wiederherstellen', aktion: 'kt_wiederherstellen', werte: { id: s(e.id).slice(2) }, frage: 'Termin „' + s(e.titel) + '“ wiederherstellen? Er steht dann wieder im Kalender.' },
          { text: 'Endgültig löschen', aktion: 'kt_endgueltig', werte: { id: s(e.id).slice(2) },
            frage: 'Termin „' + s(e.titel) + '“ endgültig löschen? Er lässt sich nicht wiederherstellen.' }] } } })),
      sortierung: {}, seite: 1, je_seite: 50, gesamt: PKL.length, leer: 'Der Papierkorb ist leer.' }] }];
} else {
  // ---------- Kalender ----------
  const heuteListe = eintraege.filter(e => s(e.tag) <= heute && s(e.bis_tag || e.tag) >= heute && (e.ganztags || s(e.bis || e.von) >= jetzt || s(e.bis_tag) > heute));
  const in7 = new Date(Date.now() + 6 * 864e5).toISOString().slice(0, 10);
  ueberblick = { kennzahlen: [
    { label: 'Einträge', wert: String(eintraege.length), neben: ZR[String(K.tage)] || '' },
    { label: 'Heute', wert: String(eintraege.filter(e => s(e.tag) <= heute && s(e.bis_tag || e.tag) >= heute).length), neben: heuteListe.length ? heuteListe.length + ' noch offen' : '' },
    { label: 'Nächste 7 Tage', wert: String(eintraege.filter(e => s(e.tag) <= in7 && s(e.bis_tag || e.tag) >= heute).length), neben: '' },
    { label: 'Ganztägig', wert: String(eintraege.filter(e => e.ganztags).length), neben: '' }],
    karten: [
      { titel: 'Offen', leer: 'Heute nichts mehr.', eintraege: heuteListe.slice(0, 5).map(e => ({ fett: zeitText(e), text: s(e.titel) || '(ohne Titel)', neben: s(e.art_text),
        ziel: hier({ termin: e.id }, 'a-termine'), ziel_text: 'Öffnen' })) },
      { titel: 'Meldungen', leer: 'Keine Meldungen.', eintraege: meldungen }] };
  // Tabelle: sortierbar (Termin, Tag, Art, Ort), 10 je Seite (Layout 11, E8/E10)
  const JE = 10;
  const ZU = D.zustand || {};
  const SP = ['titel', 'tag', 'art', 'ort'];
  const s0 = (ZU['kalender.termine'] || {}).sortierung || {};
  const so = { spalte: SP.includes(s0.spalte) ? s0.spalte : 'tag', richtung: s0.richtung === 'auf' || s0.richtung === 'ab' ? s0.richtung : 'auf' };
  const wert = (e, sp) => sp === 'tag' ? s(e.tag) + (e.ganztags ? '00:00' : s(e.von)) : sp === 'art' ? s(e.art_text).toLowerCase() : s(e[sp]).toLowerCase();
  const sortiert = eintraege.map((e, i) => [e, i]).sort((a, b) => { const c = wert(a[0], so.spalte).localeCompare(wert(b[0], so.spalte), 'de', { numeric: true }); return (so.richtung === 'ab' ? -c : c) || a[1] - b[1]; }).map(x => x[0]);
  const seiten = Math.max(1, Math.ceil(sortiert.length / JE)), bl = Math.min(seiten, Math.max(1, Number((E.seiten || {}).termine) || 1));
  abschnitte = [{ id: 'termine', titel: 'Termine', zahl: String(eintraege.length), offen_standard: true, inhalt: [
    { typ: 'filter', id: 'termine', label: 'Termine filtern', felder: [
      { typ: 'datum', name: 'von', label: 'Ab', wert: s(K.von || heute) },
      { typ: 'auswahl', name: 'tage', label: 'Zeitraum', wert: String(K.tage || '14'), optionen: Object.keys(ZR).map(k => ({ wert: k, text: ZR[k] })) },
      { typ: 'suche', name: 'q', label: 'Suchbegriff', wert: s(K.q) }] },
    { typ: 'tabelle', id: 'termine', titel: 'Termine', spalten: [{ schluessel: 'titel', titel: 'Termin', sortierbar: true }, { schluessel: 'tag', titel: 'Tag', sortierbar: true },
      { schluessel: 'zeit', titel: 'Zeit' }, { schluessel: 'art', titel: 'Art', sortierbar: true }, { schluessel: 'ort', titel: 'Ort', sortierbar: true }],
      zeilen: sortiert.slice((bl - 1) * JE, bl * JE).map(e => ({ aktiv: gew === s(e.id), zellen: {
        titel: { text: s(e.titel) || '(ohne Titel)', ziel: hier({ termin: e.id }, 'a-termine'), neben: s(e.kontext) },
        tag: tage(e), zeit: zeitText(e), art: s(e.art_text), ort: s(e.ort) || '–' } })),
      sortierung: so, seite: bl, je_seite: JE, gesamt: sortiert.length, leer: 'Keine Einträge in diesem Zeitraum.' }] }];
  // Neuer Termin: intern (vorbelegt) oder im Google Kalender, wenn eine Kalender-ID hinterlegt ist
  fenster.push({ id: 'neu', art: 'dialog', titel: 'Neuer Termin', inhalt: [{ typ: 'formular', id: 'termin-neu', aktion: 'kt_neu', spalten: 2, frage: 'Termin anlegen?',
    felder: (googleDa ? [{ typ: 'auswahl', name: 'kalender', label: 'Kalender', wert: 'intern', breite: 'voll',
      optionen: [{ wert: 'intern', text: 'Intern' }, { wert: 'google', text: 'Google Kalender' }] }] : [{ typ: 'versteckt', name: 'kalender', wert: 'intern' }])
      .concat(zeitFelder(null), [{ typ: 'textbereich', name: 'beschreibung', label: 'Notiz', wert: '', zeilen: 3, breite: 'voll' }], personFelder(null, googleDa)),
    knoepfe: [{ text: 'Abbrechen', art: 'neben', schliesst: true }, { text: 'Termin anlegen' }] }] });
  kopf.hauptaktion = { text: 'Neuer Termin', fenster: 'neu' };
  // Layout 5 (E9): Kopf-Knöpfe ohne Zähler; „Papierkorb“ zeigt der Baukasten als Symbol
  kopf.knoepfe = [{ text: 'Papierkorb', ziel: hier({ papierkorb: '1' }) }];
}

// ---------- Seitenfenster des gewählten Eintrags ----------
if (sel) {
  const paare = [{ label: 'Tag', wert: tage(sel) }, { label: 'Zeit', wert: zeitText(sel) }].concat(sel.ort ? [{ label: 'Ort', wert: s(sel.ort) }] : []);
  let inhalt = [];
  if (sel.quelle === 'intern') {
    paare.push({ label: 'Für', wert: s(sel.fuer_name) });
    if (L(sel.eingeladen_namen).length) paare.push({ label: 'Eingeladen', wert: L(sel.eingeladen_namen).map(s).join(', ') });
    paare.push({ label: 'Angelegt', wert: s(sel.erstellt_von_name) + (sel.erstellt_am ? ' am ' + s(sel.erstellt_am) : '') });
    if (sel.geaendert_am) paare.push({ label: 'Geändert', wert: s(sel.geaendert_von_name) + ' am ' + s(sel.geaendert_am) });
    inhalt = [{ typ: 'paare', eintraege: paare }].concat(sel.notiz ? [{ typ: 'text', text: s(sel.notiz) }] : []);
    const id = s(sel.id).slice(2);
    if (sel.geloescht) {
      inhalt.push({ typ: 'hinweis', text: 'Dieser Termin liegt seit ' + s(sel.geloescht_am) + ' im Papierkorb.' },
        { typ: 'aktion', text: 'Wiederherstellen', aktion: 'kt_wiederherstellen', werte: { id }, frage: 'Termin „' + s(sel.titel) + '“ wiederherstellen? Er steht dann wieder im Kalender.' },
        { typ: 'aktion', text: 'Endgültig löschen', aktion: 'kt_endgueltig', werte: { id }, frage: 'Termin „' + s(sel.titel) + '“ endgültig löschen? Er lässt sich nicht wiederherstellen.' });
    } else {
      inhalt.push({ typ: 'unterueberschrift', text: 'Termin ändern' },
        { typ: 'formular', id: 'termin-aendern', aktion: 'kt_aendern', werte: { id }, spalten: 2, frage: 'Termin ändern?',
          felder: zeitFelder(sel).concat([{ typ: 'textbereich', name: 'beschreibung', label: 'Notiz', wert: s(sel.notiz), zeilen: 3, breite: 'voll' }], personFelder(sel, false)),
          knoepfe: [{ text: 'Änderung speichern' }] },
        { typ: 'aktion', text: 'In den Papierkorb', aktion: 'kt_papierkorb', werte: { id },
          frage: 'Termin „' + s(sel.titel) + '“ in den Papierkorb legen? Im Papierkorb kannst du ihn wiederherstellen oder endgültig löschen.' });
    }
  } else if (sel.quelle === 'google') {
    const t = sel.g || {};
    inhalt = [{ typ: 'paare', eintraege: paare.concat([{ label: 'Kalender', wert: 'Google Kalender' }]) }].concat(t.notiz ? [{ typ: 'text', text: s(t.notiz) }] : []);
    const gFelder = [
      { typ: 'text', name: 'titel', label: 'Titel', pflicht: true, wert: s(t.titel), breite: 'voll' },
      { typ: 'haken', name: 'ganztaegig', label: 'ganztägig', wert_an: '1', an: !!t.ganz, breite: 'voll' },
      { typ: 'datum_zeit', name: 'start', label: 'Beginn', wert: !t.ganz ? s(t.start) : '' },
      { typ: 'datum_zeit', name: 'ende', label: 'Ende', wert: !t.ganz ? s(t.ende) : '' },
      { typ: 'datum', name: 'start_tag', label: 'Erster Tag (ganztägig)', wert: s(t.tag), zeigen_wenn: { feld: 'ganztaegig', werte: ['1'] } },
      { typ: 'datum', name: 'ende_tag', label: 'Letzter Tag (ganztägig)', wert: t.ganz ? s(t.ende_tag) : (/^\d{4}-\d{2}-\d{2}/.test(s(t.ende)) ? s(t.ende).slice(0, 10) : s(t.tag)),
        zeigen_wenn: { feld: 'ganztaegig', werte: ['1'] } },
      { typ: 'text', name: 'ort', label: 'Ort', wert: s(t.ort), breite: 'voll' }]
      .concat(t.notiz_fest ? [{ typ: 'versteckt', name: 'beschreibung_behalten', wert: '1' }, { typ: 'anzeige', name: 'notiz_anzeige', label: 'Notiz', wert: 'bleibt unverändert (Formatierung aus dem Kalender)', breite: 'voll' }]
        : [{ typ: 'textbereich', name: 'beschreibung', label: 'Notiz', wert: s(t.beschreibung), zeilen: 3, breite: 'voll' }]);
    inhalt.push({ typ: 'unterueberschrift', text: 'Termin ändern' },
      { typ: 'formular', id: 'termin-aendern', aktion: 'termin_aendern', werte: { termin: sel.gid }, spalten: 2, frage: 'Termin ändern? Teilnehmende werden nicht benachrichtigt.',
        felder: gFelder, knoepfe: [{ text: 'Änderung speichern' }] },
      { typ: 'aktion', text: 'Termin löschen', aktion: 'termin_loeschen', werte: { termin: sel.gid }, frage: 'Termin „' + s(sel.titel) + '“ löschen? Der Termin wird im verbundenen Kalender gelöscht.' });
  } else {
    // Eintrag eines Pakets: ändern nur über die Kalenderquelle des Pakets, soweit es erlaubt ist
    paare.push({ label: 'Art', wert: s(sel.art_text) });
    if (sel.kontext) paare.push({ label: 'Bezug', wert: s(sel.kontext) });
    if (sel.status_text) paare.push({ label: 'Stand', wert: s(sel.status_text) });
    paare.push({ label: 'Paket', wert: s(sel.quelle_name) });
    inhalt = [{ typ: 'paare', eintraege: paare }].concat(sel.notiz ? [{ typ: 'text', text: s(sel.notiz) }] : []);
    if (sel.ziel && sel.ziel.seite) inhalt.push({ typ: 'aktion', text: s(sel.ziel_text) || 'Öffnen', ziel: sel.ziel });
    if (sel.hinweis) inhalt.push({ typ: 'hinweis', text: s(sel.hinweis) });
    const fe = L(sel.felder).filter(f => f && /^[a-z_]{1,30}$/.test(s(f.name)) && ['datum', 'datum_zeit'].includes(s(f.typ)));
    if (sel.aenderbar === true && fe.length) inhalt.push({ typ: 'unterueberschrift', text: 'Datum ändern' },
      { typ: 'formular', id: 'eintrag-aendern', aktion: 'kt_quelle_aendern', werte: { quelle: s(sel.quelle), eintrag: s(sel.eintrag) }, spalten: 2,
        frage: s(sel.art_text) + ' „' + s(sel.titel) + '“ ändern?', felder: fe.map(f => ({ typ: s(f.typ), name: s(f.name), label: s(f.label), wert: s(f.wert) })),
        knoepfe: [{ text: 'Änderung speichern' }] });
  }
  fenster.push({ id: 'termin', art: 'seitenfenster', offen: true, titel: s(sel.titel) || '(ohne Titel)', untertitel: tage(sel) + ' · ' + zeitText(sel),
    schliessen_ziel: hier({}, pk ? 'a-papierkorb' : 'a-termine'), inhalt });
}
